 items.append({'id':f'{SUB}-i{id:02d}','kcs':[kc],'kind':'numeric','difficulty':diff,'command_word':'Calculate','source':{'type':'generated'},'stem':stem,'marks':2,'answer':ans(value,unit),'distractors':[{'value':round(wrong,6),'misconception':'m2'}],'explanation':ex,'hints':['Identify whether the source approaches or recedes.','Choose the denominator from the direction of motion.','Write $f_o=f_s v/(v\\pm v_s)$ and insert the given quantities.']})
