items.append({'id':f'{SUB}-i04','kcs':[K2],'kind':'numeric','difficulty':3,'command_word':'Calculate','source':{'type':'generated'},'stem':'A source emits $[[fs]]$ Hz sound and moves directly towards a stationary observer at $[[vs]]\\,\\mathrm{m\\,s^{-1}}$. The sound speed is $[[v]]\\,\\mathrm{m\\,s^{-1}}$. Calculate the observed frequency.','marks':2,'answer':ans(fo(600,340,20,True)),'template':{'params':{'fs':{'min':500,'max':800,'step':100},'vs':{'min':20,'max':40,'step':10},'v':{'choices':[330,340]}},'derived':{},'answer':'fs*v/(v-vs)','distractors':[{'expr':'fs*v/(v+vs)','misconception':'m2'}],'constraints':['vs<v']},'explanation':'For an approaching source, use $f_o=f_s v/(v-v_s)$.','hints':['Check the direction of source motion.','Decide which sign compresses wavefront spacing.','Substitute into the moving-source expression.']})
items.append({'id':f'{SUB}-i05','kcs':[K1],'kind':'short','difficulty':2,'command_word':'Explain','source':{'type':'generated'},'stem':'Explain why a stationary listener hears a higher frequency as a sound source moves directly towards them.','marks':2,'rubric':[{'point':'Successive wavefronts are closer together ahead of the moving source.','keywords':[['wavefront','waves'],['closer','compressed','shorter']]},{'point':'At unchanged sound speed, shorter wavelength means higher frequency.','keywords':[['wavelength'],['frequency','higher']]}],'explanation':'The moving source compresses wavefront spacing; with sound speed fixed, $v=f\\lambda$ makes the observed frequency higher.','hints':['Think about successive crests emitted by a moving source.','Compare their spacing in front of and behind the source.','Relate wavelength and frequency using $v=f\\lambda$.']})
items.append({'id':f'{SUB}-i06','kcs':[K1],'kind':'short','difficulty':4,'command_word':'Explain','source':{'type':'generated'},'stem':'A siren approaches a stationary observer while slowing down, then moves away while speeding up. Explain how the frequency heard changes in each stage.','marks':2,'rubric':[{'point':'During decelerating approach, observed frequency decreases but remains above emitted frequency.','keywords':[['approach','towards'],['decrease','falls']]},{'point':'During accelerating recession, observed frequency decreases and remains below emitted frequency.','keywords':[['away','recession'],['decrease','falls']]}],'explanation':'Slower approach reduces the positive shift; faster recession increases the negative shift. In both stages the heard frequency decreases.','hints':['Treat approach and recession separately.','Track how source speed changes each denominator.','For approach use $v-v_s$; for recession use $v+v_s$.']})
pack={'subtopic':SUB,'spec':'9702','version':1,'note':'Subjects/9702 Physics/07 Waves/7.3 Doppler effect for sound waves.md','outline':'A moving sound source emits successive wavefronts from different positions. For a stationary observer, approach shortens the wavelength and raises the observed frequency; recession lengthens it and lowers the frequency. Sound speed in a fixed medium remains unchanged. Use $f_o=f_s v/(v-v_s)$ for approach and $f_o=f_s v/(v+v_s)$ for recession, where $v_s$ is source speed. A passing source changes from the higher to lower observed frequency.','misconceptions':mis,'worked':worked,'items':items,'flashcards':[{'id':'fc1','kc':K1,'front':'State the Doppler effect for a moving sound source and stationary observer.','back':'The observed frequency differs from the source frequency when the sound source moves relative to a stationary observer.'},{'id':'fc2','kc':K2,'front':'State the moving-source Doppler formula and sign convention.','back':'$f_o=f_s v/(v\\pm v_s)$: use minus for approach and plus for recession; $v$ is sound speed and $v_s$ source speed.'}],'diagrams':[]}
